<script setup>
import {s,run,loadRows,callLabel,responseLabel,resetRowFilters} from './store';
defineProps({fieldsOnly:Boolean});
const fields=[{key:'call_status',label:'Tình trạng gọi xác nhận'},{key:'position',label:'Chức vụ'},{key:'utm_content',label:'utm_content'},{key:'company',label:'Công ty'},{key:'department',label:'Phòng / nhóm'},{key:'staff_code',label:'Mã nhân viên'},{key:'assignee_name',label:'Người phụ trách'},{key:'contact_response',label:'Phản hồi'}];
</script><template><section class="card stack" :class="{'compact-filter-panel':fieldsOnly}" aria-label="Bộ lọc dữ liệu đăng ký"><div v-if="!fieldsOnly" class="row"><MInput v-model="s.query" placeholder="Tìm tên, email, điện thoại, công ty, tracking" aria-label="Tìm đăng ký" @keyup.enter="s.page=1;run(loadRows)"/><MButton variant="secondary" @click="s.page=1;run(loadRows)">Tìm kiếm</MButton><MButton variant="link" @click="resetRowFilters">Xóa bộ lọc</MButton></div><div class="grid-form"><label v-for="field in fields" :key="field.key" class="field">{{field.label}}<MCombobox v-model="s.rowFilters[field.key]" multiple :options="(s.rowOptions[field.key]||[]).map(value=>({value,label:field.key==='call_status'?callLabel(value):field.key==='contact_response'?responseLabel(value):value||'Chưa có dữ liệu'}))" placeholder="Tất cả" :aria-label="field.label"/></label><label class="field">Từ ngày submit<MDatePicker v-model="s.rowFrom"/></label><label class="field">Đến ngày submit<MDatePicker v-model="s.rowTo"/></label></div><p v-if="!fieldsOnly" class="muted">Có thể chọn nhiều giá trị trong mỗi bộ lọc. Các bộ lọc được kết hợp đồng thời. Ngày Việt Nam (UTC+7).</p></section></template>
